-- Read-only schema metadata. Never selects application rows, auth rows or secrets.
-- Scope: current public schema, plus auth triggers invoking public functions.
set search_path = public;
select jsonb_build_object(
 'format_version',1,
 'captured_at',current_timestamp,
 'source_project','ayiuxjlfazkjmmtlvhsl',
 'database_version',current_setting('server_version'),
 'extensions',(select coalesce(jsonb_agg(format('CREATE EXTENSION IF NOT EXISTS %I WITH SCHEMA %I;',e.extname,n.nspname) order by e.extname),'[]') from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname<>'plpgsql'),
 'unsupported',(select coalesce(jsonb_agg(format('%s.%s kind=%s',n.nspname,c.relname,c.relkind)),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind not in ('r','i','v','S') and not exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='e')),
 'schema_acl',(select coalesce(jsonb_agg(format('GRANT %s ON SCHEMA public TO %s%s;',x.privilege_type,case when x.grantee=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(x.grantee)) end,case when x.is_grantable then ' WITH GRANT OPTION' else '' end)),'[]') from pg_namespace n cross join lateral aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x where n.nspname='public'),
 'owners',(select coalesce(jsonb_agg(ddl order by ddl),'[]') from (select format('ALTER %s public.%I OWNER TO %I;',case c.relkind when 'r' then 'TABLE' when 'v' then 'VIEW' when 'S' then 'SEQUENCE' end,c.relname,pg_get_userbyid(c.relowner)) ddl from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','v','S') union all select format('ALTER FUNCTION %s OWNER TO %I;',p.oid::regprocedure,pg_get_userbyid(p.proowner)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') union all select format('ALTER TYPE public.%I OWNER TO %I;',t.typname,pg_get_userbyid(t.typowner)) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typtype='e') q),
 'type_revoke',(select coalesce(jsonb_agg(format('REVOKE ALL ON TYPE public.%I FROM PUBLIC, anon, authenticated, service_role;',t.typname)),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typtype='e'),
 'type_acl',(select coalesce(jsonb_agg(format('GRANT %s ON TYPE public.%I TO %s%s;',x.privilege_type,t.typname,case when x.grantee=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(x.grantee)) end,case when x.is_grantable then ' WITH GRANT OPTION' else '' end)),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace cross join lateral aclexplode(coalesce(t.typacl,acldefault('T',t.typowner))) x where n.nspname='public' and t.typtype='e'),
 'enums',(select coalesce(jsonb_agg(ddl order by name),'[]') from (select t.typname name,format('CREATE TYPE public.%I AS ENUM (%s);',t.typname,string_agg(quote_literal(e.enumlabel),', ' order by e.enumsortorder)) ddl from pg_type t join pg_namespace n on n.oid=t.typnamespace join pg_enum e on e.enumtypid=t.oid where n.nspname='public' group by t.typname) q),
 'sequences',(select coalesce(jsonb_agg(format('CREATE SEQUENCE public.%I AS %s INCREMENT BY %s MINVALUE %s MAXVALUE %s START WITH %s CACHE %s %s;',c.relname,format_type(s.seqtypid,null),s.seqincrement,s.seqmin,s.seqmax,s.seqstart,s.seqcache,case when s.seqcycle then 'CYCLE' else 'NO CYCLE' end) order by c.relname),'[]') from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
 'tables',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'ddl',format('CREATE TABLE public.%I (%s);',c.relname,(select string_agg(format('%I %s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),case when a.attgenerated<>'' then ' GENERATED ALWAYS AS ('||pg_get_expr(d.adbin,d.adrelid)||') STORED' when a.attidentity<>'' then case when a.attidentity='a' then ' GENERATED ALWAYS AS IDENTITY' else ' GENERATED BY DEFAULT AS IDENTITY' end else '' end,case when a.attnotnull then ' NOT NULL' else '' end),', ' order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)),'rls',format('ALTER TABLE public.%I %s ROW LEVEL SECURITY; ALTER TABLE public.%I %s FORCE ROW LEVEL SECURITY;',c.relname,case when c.relrowsecurity then 'ENABLE' else 'DISABLE' end,c.relname,case when c.relforcerowsecurity then '' else 'NO' end)) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),
 'defaults',(select coalesce(jsonb_agg(format('ALTER TABLE public.%I ALTER COLUMN %I SET DEFAULT %s;',c.relname,a.attname,pg_get_expr(d.adbin,d.adrelid)) order by c.relname,a.attnum),'[]') from pg_attrdef d join pg_attribute a on a.attrelid=d.adrelid and a.attnum=d.adnum join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and a.attgenerated='' and a.attidentity=''),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('name',p.oid::regprocedure::text,'requires_relation_type',exists(select 1 from pg_type rt where rt.typrelid<>0 and (rt.oid=p.prorettype or rt.oid=any(coalesce(p.proallargtypes,p.proargtypes::oid[])))),'ddl',pg_get_functiondef(p.oid),'acl',(select jsonb_agg(format('GRANT %s ON FUNCTION %s TO %s%s;',x.privilege_type,p.oid::regprocedure,case when x.grantee=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(x.grantee)) end,case when x.is_grantable then ' WITH GRANT OPTION' else '' end)) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x)) order by p.oid::regprocedure::text),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
 'constraints',(select coalesce(jsonb_agg(format('ALTER TABLE public.%I ADD CONSTRAINT %I %s;',c.relname,k.conname,pg_get_constraintdef(k.oid,true)) order by case when k.contype='f' then 1 else 0 end,c.relname,k.conname),'[]') from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
 'indexes',(select coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid)||';' order by i.indexrelid::regclass::text),'[]') from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not exists(select 1 from pg_constraint k where k.conindid=i.indexrelid)),
 'views',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'ddl',format('CREATE VIEW public.%I%s AS %s',c.relname,case when c.reloptions is not null then ' WITH ('||array_to_string(c.reloptions,',')||')' else '' end,pg_get_viewdef(c.oid,true)),'depends',(select coalesce(jsonb_agg(distinct dc.relname),'[]') from pg_rewrite r join pg_depend d on d.classid='pg_rewrite'::regclass and d.objid=r.oid join pg_class dc on dc.oid=d.refobjid and d.refclassid='pg_class'::regclass join pg_namespace dn on dn.oid=dc.relnamespace where r.ev_class=c.oid and dn.nspname='public' and dc.relkind='v' and dc.oid<>c.oid)) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='v'),
 'triggers',(select coalesce(jsonb_agg(pg_get_triggerdef(t.oid,true)||';' order by t.tgrelid::regclass::text,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace pn on pn.oid=p.pronamespace where not t.tgisinternal and (n.nspname='public' or (n.nspname='auth' and pn.nspname='public'))),
 'policies',(select coalesce(jsonb_agg(format('CREATE POLICY %I ON public.%I AS %s FOR %s TO %s%s%s;',p.polname,c.relname,case when p.polpermissive then 'PERMISSIVE' else 'RESTRICTIVE' end,case p.polcmd when 'r' then 'SELECT' when 'a' then 'INSERT' when 'w' then 'UPDATE' when 'd' then 'DELETE' else 'ALL' end,(select string_agg(case when r=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(r)) end,',') from unnest(p.polroles) r),case when p.polqual is not null then ' USING ('||pg_get_expr(p.polqual,p.polrelid)||')' else '' end,case when p.polwithcheck is not null then ' WITH CHECK ('||pg_get_expr(p.polwithcheck,p.polrelid)||')' else '' end) order by c.relname,p.polname),'[]') from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
 'relation_acl',(select coalesce(jsonb_agg(format('GRANT %s ON %s public.%I TO %s%s;',x.privilege_type,case when c.relkind='S' then 'SEQUENCE' else 'TABLE' end,c.relname,case when x.grantee=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(x.grantee)) end,case when x.is_grantable then ' WITH GRANT OPTION' else '' end) order by c.relname,x.grantee,x.privilege_type),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))) x where n.nspname='public' and c.relkind in ('r','v','S')),
 'column_acl',(select coalesce(jsonb_agg(format('GRANT %s (%I) ON TABLE public.%I TO %s%s;',x.privilege_type,a.attname,c.relname,case when x.grantee=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(x.grantee)) end,case when x.is_grantable then ' WITH GRANT OPTION' else '' end)),'[]') from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(a.attacl) x where n.nspname='public'),
 'default_acl',(select coalesce(jsonb_agg(format('ALTER DEFAULT PRIVILEGES FOR ROLE %I IN SCHEMA public GRANT %s ON %s TO %s%s;',pg_get_userbyid(d.defaclrole),x.privilege_type,case d.defaclobjtype when 'r' then 'TABLES' when 'S' then 'SEQUENCES' when 'f' then 'FUNCTIONS' when 'T' then 'TYPES' end,case when x.grantee=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(x.grantee)) end,case when x.is_grantable then ' WITH GRANT OPTION' else '' end)),'[]') from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) x where n.nspname='public')
) as schema_metadata;
